  "rcloneRemote.hint": "Windows 또는 Samba 공유나 Nextcloud 같은 WebDAV 서버에 호스트에 마운트하지 않고 연결합니다. restic은 마운트된 CIFS 공유에 저장소를 두지 않도록 권고하며, 이 방식은 마운트 자체를 거치지 않습니다. 비밀번호는 rclone에 전달되어 rclone 고유의 형식으로 저장되며, 평문으로 보관되지 않습니다. restic과 rclone 모두 NFS를 지원하지 않으므로 여기서는 NFS를 제공하지 않습니다. NFS를 사용하려면 익스포트를 Unraid에 마운트하고 백업 경로를 그곳으로 설정하세요.",
