  "coverage.title": "백업 안 됨",
  "coverage.hint": "이 서버에서 자동 백업이 다루지 않는 모든 항목입니다. 위의 보호 상태 카드는 예약된 백업이 제때 실행됐는지 알려주고, 이 카드는 아예 예약조차 되지 않은 것을 보여줍니다. 다른 페이지에는 나오지 않는 내용입니다. 직접 꺼 둔 백업 도메인은 여기서 세지 않습니다. 추가하지 않은 ZFS 데이터세트도 여기서는 세지 않습니다. ZFS 페이지에 목록이 있습니다.",
