  "settings.retentionOffsiteTitle": "오프사이트 보존",
  "settings.retentionOffsiteHint": "오프사이트 저장소를 위한 별도 정책으로, 아카이브로 더 오래 보관할 수 있습니다. 모두 0 = 모든 오프사이트 백업 보관(오프사이트 정리 없음).",
  "settings.retentionCombineInfo": "다섯 가지 규칙은 OR로 결합됩니다: 어느 한 규칙이라도 보관하려는 스냅샷은 남습니다. 고정된 개수로 합산되지 않습니다. 백업된 각 항목에 개별적으로 적용됩니다.",

  "rclone.title": "오프사이트 (rclone)",
  "rclone.hint": "rclone 설정을 붙여넣어 클라우드(Backblaze B2, S3, Google Drive 등)로 백업합니다. 암호화하여 저장됩니다. SMB/NFS는 rclone이 필요 없습니다. Unraid에 공유를 마운트하고 백업 경로를 그곳으로 설정하세요.",
  "rclone.configured": "구성된 원격",
  "rclone.pathHint": "그런 다음 백업 경로를 \"rclone:<remote>:<bucket>/path\"로 설정하면 해당 도메인이 오프사이트로 전송됩니다.",
  "cloud.title": "공유 클라우드 자격 증명 (S3 / restic REST)",
  "cloud.hint": "rclone 없이 원격 restic 백엔드용 자격 증명. 저장 후 백업 경로를 원격 저장소로 설정하세요. 예: s3:s3.amazonaws.com/bucket/path, rest:http://host:8000/repo, b2:bucket:path 또는 sftp:user@host:/repo. 비밀 값은 암호화되어 저장되며 다시 표시되지 않습니다.",
  "cloud.secretSet": "저장됨. 유지하려면 비워 두세요",
  "cloud.storageClass.label": "오프사이트 스토리지 클래스",
  "cloud.storageClass.default": "(제공자 기본값)",
  "cloud.storageClass.hint": "네이티브 S3 백엔드 (s3: 로 시작하는 리포지토리) 에만 적용됩니다. 딥 아카이브 계층 (Glacier Flexible Retrieval, Deep Archive) 은 restic 복원을 망가뜨리므로 의도적으로 제공하지 않습니다.",
  "cloud.credSets.title": "추가 자격 증명 세트",
  "cloud.credSets.hint": "하나 이상의 오프사이트 대상에 위의 것을 공유하는 대신 자체 S3 또는 restic REST 자격 증명을 부여합니다.",
  "cloud.credSets.add": "자격 증명 세트 추가",
  "cloud.credSets.name": "이름",
  "cloud.credSets.none": "아직 추가 자격 증명 세트가 없습니다.",
  "export.encrypt.hint": "restic 리포지토리는 이미 암호화되어 있습니다. 이것은 평문 내보내기 산출물 (컨테이너 및 VM 의 tar.gz 와 그 xml, 그리고 플래시 zip) 을 age 로 선택적으로 암호화하여 서버 밖에 안전하게 저장하거나 옮길 수 있게 합니다.",
  "export.encrypt.ageInfo": "age (age-encryption.org) 는 작고 현대적인 파일 암호화 도구입니다. 하나 이상의 수신자를 위해 파일을 봉인하는, GPG보다 더 간단한 대안입니다.",
  "export.encrypt.enable": "age 로 내보내기 암호화",
  "export.encrypt.enableHint": "켜면 컨테이너, VM, 플래시 내보내기가 디스크에 기록되기 전에 age 로 봉인되고 .age 접미사가 붙습니다.",
  "export.encrypt.kitSealed": "복구 키트도 함께 봉인되어 bombvault-recovery-kit.md.age 로 전달됩니다. 읽을 수 있는 텍스트(ASCII 아머)로 남아 있어 비밀번호 관리자에 붙여넣거나 인쇄할 수 있지만, 열려면 age 개인 키가 필요합니다. 그 키는 키트 자체에 의존하지 않는 곳에 보관하세요.",
  "export.encrypt.recipients": "age 수신자",
  "export.encrypt.recipientsHint": "한 줄에 수신자 하나. age 공개 키 (age1...) 또는 SSH 공개 키를 사용하세요. 서버 밖에서 복호화하려면 해당 개인 키가 필요합니다. 암호화가 켜져 있고 유효한 수신자가 없으면 내보내기는 평문을 쓰는 대신 실패합니다.",
  "export.encrypt.recipientsPlaceholder": "age1qz...\nssh-ed25519 AAAA...",
  "export.encrypt.recipientsRequired": "age 수신자를 최소한 하나 추가하세요. 그렇지 않으면 암호화된 내보내기가 실패합니다.",
