  "runReason.dbimportPrepare": "가져오기가 시작되기도 전에 실패했습니다. 이전 데이터는 제자리로 돌아왔습니다",
  "runReason.dbimportRollback": "가져오기가 실패했고 이전 데이터를 제자리에 되돌리지 못했습니다",
