  "dbdump.importConfirmNoVersion": "이 {engine} 덤프를 {container}에 가져올까요? BombVault는 컨테이너를 멈추고 데이터 폴더를 옆으로 옮긴 뒤(그대로 보관하며 아무것도 지우지 않습니다), 빈 데이터 폴더로 컨테이너를 시작해 덤프를 가져옵니다. 이 데이터베이스를 쓰는 응용 프로그램은 덤프를 받은 시점의 상태를 보게 됩니다.",
