  "offsite.prune.info": "이 단계는 무슨 일이 일어나는지 알려줄 뿐, 아무것도 설정하지 않습니다. 이 복사본이 정리되는지는 4단계의 append-only와 설정, 오프사이트 보존의 보관 값으로 결정됩니다. append-only 복사본을 그래도 정리하려면 저장소 측에서 restic forget --prune을 실행하세요. 별도의 일정으로 돌리거나, append-only가 아닌 두 번째 REST 서버를 잠시 띄워 그쪽으로 정리한 뒤 다시 내리면 됩니다.",
  "offsite.prune.stateFarSide": "여기서는 이 복사본을 정리하지 않습니다. append-only가 켜져 있어 BombVault는 추가만 하며, 정리는 저장소 측의 몫입니다.",
  "offsite.prune.statePolicy": "BombVault는 복제할 때마다 오프사이트 보존 정책에 따라 이 복사본을 정리합니다.",
  "offsite.prune.stateNone": "이 복사본을 정리하는 것이 없습니다. append-only가 꺼져 있고 오프사이트 보관 값이 모두 0이라, 디스크가 버티는 한 계속 늘어납니다.",
