  "recovery.foreignTitle": "다른 BombVault 저장소에서 복원",
  "recovery.abTitle": "Appdata.Backup 플러그인에서 가져오기",
  "recovery.abIntro": "Appdata.Backup 플러그인이 쓴 아카이브를 해당 컨테이너의 복원 지점으로 바꿉니다. 날짜는 플러그인이 만든 시점입니다. 아카이브는 읽기만 하고 절대 바꾸거나 지우지 않습니다. 각 아카이브는 저장소 옆에 풀어서 백업한 뒤 풀어 둔 사본을 다시 지우므로, 그곳에 가장 큰 아카이브가 들어갈 공간이 있어야 합니다.",
