  "recovery.foreignCredsIntro": "원격 저장소로 보이므로 상대 서버 백엔드의 자격 증명이 필요합니다. 이 자격 증명은 이번 세션에만 사용되며 절대 저장되지 않습니다. 내 오프사이트 자격 증명은 여기서 일부러 재사용하지 않습니다. 방금 입력한 주소로 전송되기 때문입니다.",
