  "files.repoLocked": "세트에 백업이 생긴 뒤에는 변경할 수 없습니다. 백업은 기록된 저장소에 그대로 남고 옮겨지지 않습니다. 먼저 이 세트의 백업을 삭제하거나 새 세트를 만드십시오.",
