  "repos.title": "저장소",
  "repos.intro": "백업을 기록할 수 있는 위치입니다. 여기서 하나 만든 다음 도메인 저장소 대신 개별 컨테이너, 가상 머신, 폴더 세트에서 선택하세요.",
  "repos.itemLabel": "저장소",
