  "repos.itemHint": "이 항목의 백업이 어디로 갈지입니다. 이 항목에 전용 저장소가 필요한 경우가 아니면 도메인 저장소로 두세요. 흔한 이유는 거의 바뀌지 않는 큰 항목이고 외부 사본만 필요한 경우입니다. 목록에는 설정에서 만든 것이 들어 있습니다.",
  "repos.itemLocked": "항목에 백업이 생긴 뒤에는 바꿀 수 없습니다. 백업은 기록된 저장소에 남고 아무것도 옮기지 않습니다. 먼저 그 항목의 백업을 삭제하세요.",
