  "repos.location": "위치",
  "repos.locationPlaceholder": "backups/cold 또는 b2:bucket/path",
  "repos.locationHint": "호스트 마운트 아래의 폴더, 또는 b2:bucket/path, s3:..., sftp:..., rest:..., rclone:... 같은 원격 restic 저장소입니다. 원격에는 중간 로컬 사본 없이 바로 기록합니다.",
  "repos.locationLocked": "여기로 백업하는 것이 있는 동안에는 위치를 옮길 수 없습니다. 지금까지 기록된 것은 그대로 남으므로 다음 백업은 빈 저장소에 성공해 버립니다. 두 번째를 추가하고 항목을 그쪽으로 돌리세요.",
