  "anomaly.title": "이상 징후",
  "anomaly.cardHint": "BombVault는 항목의 모든 백업을 이전 백업과 비교해 어울리지 않는 것을 짚어 줍니다. 평소보다 훨씬 많은 새 데이터, 데이터 대부분의 다시 쓰기, 급격히 줄거나 커진 원본, 작아진 데이터베이스 덤프, 갑자기 훨씬 오래 걸리는 백업, 반복되는 실패, 더 이상 통과하지 못하는 복원 점검, 곧 가득 찰 디스크입니다. 대부분의 점검에는 먼저 항목당 백업 10회가 필요합니다. ZFS 항목은 데이터세트별로 검사하므로, 큰 트리 안에서도 비워진 하위 데이터세트가 드러납니다.",
