  "anomaly.sentence.newData": "{name}이(가) 백업 한 번에 새 데이터 {bytes}를 추가했습니다. 평소에는 많아야 {typical}입니다.",
  "anomaly.sentence.newDataRewrite": "{name}이(가) 백업 한 번에 {bytes}를 다시 썼습니다. 저장 대상 전체({source})의 절반 이상입니다. 그만큼 바꾸지 않았다면 파일이 암호화되었거나 교체되었는지 확인하세요.",
  "anomaly.sentence.newDataRenamed": "이전 백업이 있는데도 {name}의 모든 파일이 새것처럼 보이고, {source} 중 {bytes}가 다시 저장되었습니다. 이름 변경과 다시 쓰기가 동시에 일어나는 것은 랜섬웨어의 전형입니다. 무엇보다 먼저 파일을 확인하세요.",
  "anomaly.sentence.newDataFull": "이전 백업이 하나도 맞지 않아 BombVault가 {name}의 모든 파일을 다시 읽었습니다(새 저장소, 새 폴더 또는 바뀐 암호화). 저장된 새 데이터: {bytes}.",
  "anomaly.sentence.sourceCollapse": "{name}이(가) 거의 비어 있습니다: {current}, 평소 {typical}. 데이터가 삭제되었는지, 디스크가 마운트되지 않았는지 확인하세요.",
